function x1_protocol_seed():void{if(!x1_db())return;$rows=[['PANEL_API','direct_http','GET; Accept application/json; User-Agent WAVEO-Panel','portals[{name,url}]','PortalSetup.fetchPortals()','confirmed','embedded direct URL','/api/'],['devicePollPendingActivationsByMac','manual_cloud_function','macAddress','jobs,data,jobId,playlist','APK manual HTTPS Cloud Function caller','confirmed','europe-west1 original project','/api/functions/devicePollPendingActivationsByMac.php'],['deviceAckActivationJob','manual_cloud_function','jobId,macAddress,success,failed,result,message','ack','APK post-import acknowledgement','confirmed','europe-west1 original project','/api/functions/deviceAckActivationJob.php'],['verifyAccessCodeDevice','firebase_callable','code,deviceId,deviceInfo','status,linked,authorized,active,entitlementId,planId','Firebase Callable caller','confirmed','original Firebase project','/api/functions/verifyAccessCodeDevice.php'],['redeemAccessCode','firebase_callable','code,deviceId,deviceInfo','premium state,remainingActivations','Firebase Callable caller','confirmed','original Firebase project','/api/functions/redeemAccessCode.php'],['getPremiumCheckoutConfig','firebase_callable','locale','offers,amountLabel','SubscriptionActivity callable','confirmed','original Firebase project','/api/functions/getPremiumCheckoutConfig.php'],['createSyncPairingCode','firebase_callable','sourceDeviceId,sourceDeviceInfo,ttlSeconds,requestedOptions','code,sessionId,expiresAt,rateLimit','pairing repository/model','strong','original Firebase project','/api/cloud/createPairingCode.php'],['confirmSyncPairing','firebase_callable','code,targetDeviceId,targetDeviceInfo','sessionId,status,source/target info','pairing confirm flow','strong','original Firebase project','/api/cloud/confirmPairingCode.php'],['pushPlaylists','firebase_callable','sessionId,playlists,mode,delta,revision','mapped,conflicts,snapshot','sync builder + logs','strong','original Firebase project','/api/cloud/pushPlaylists.php'],['pullPlaylists','firebase_callable','sessionId,lastRevision,mode','playlists,lastRemoteSnapshotVersion','sync parser + logs','strong','original Firebase project','/api/cloud/pullPlaylists.php'],['m3uLinks','firebase_rtdb','QR/M3U onboarding node','M3U onboarding data','RTDB URL + node evidence','confirmed','Companion RTDB','/api/rtdb/m3uLinks.php'],];foreach($rows as $r)x1_db_exec('INSERT INTO protocol_contracts(id,name,transport,request_schema,response_schema,evidence,confidence,stock_routing,x1_endpoint,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(name) DO UPDATE SET transport=excluded.transport,request_schema=excluded.request_schema,response_schema=excluded.response_schema,evidence=excluded.evidence,confidence=excluded.confidence,stock_routing=excluded.stock_routing,x1_endpoint=excluded.x1_endpoint,updated_at=excluded.updated_at',[x1_id(),...$r,date('c')]);}function x1_http_post_json(string $url,array $payload,array $headers=[]):array{if(!function_exists('curl_init'))return['ok'=>false,'error'=>'curl_missing'];$ch=curl_init($url);$h=['Content-Type: application/json'];foreach($headers as $k=>$v)$h[]=$k.': '.$v;curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_SLASHES),CURLOPT_HTTPHEADER=>$h,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_CONNECTTIMEOUT=>5]);$body=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return['ok'=>$err===''&&$code>=200&&$code<300,'http'=>$code,'body'=>$body,'error'=>$err];}function x1_integration_send(string $event,string $title,string $body,array $meta=[]):array{$results=[];if(!x1_db())return $results;foreach(x1_db_all('SELECT * FROM integrations WHERE enabled=1')as $i){try{$cfg=$i['config_enc']!==''?json_decode(x1_decrypt_secret($i['config_enc']),true):[];$cfg=is_array($cfg)?$cfg:[];if($i['type']==='telegram'&&!empty($cfg['bot_token'])&&!empty($cfg['chat_id'])){$url='https://api.telegram.org/bot'.$cfg['bot_token'].'/sendMessage';$r=x1_http_post_json($url,['chat_id'=>$cfg['chat_id'],'text'=>$title."\n".$body]);}elseif($i['type']==='discord'&&!empty($cfg['webhook_url'])){$r=x1_http_post_json($cfg['webhook_url'],['content'=>'**'.$title."**\n".$body]);}elseif($i['type']==='webhook'&&!empty($cfg['url'])){$payload=['event'=>$event,'title'=>$title,'body'=>$body,'meta'=>$meta,'at'=>date('c')];$headers=[];if(!empty($cfg['secret']))$headers['X-X1-Signature']='sha256='.hash_hmac('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES),$cfg['secret']);$r=x1_http_post_json($cfg['url'],$payload,$headers);}else{$r=['ok'=>false,'error'=>'incomplete_config'];}$results[]=['id'=>$i['id'],'name'=>$i['name'],'result'=>$r];}catch(Throwable $e){$results[]=['id'=>$i['id'],'name'=>$i['name'],'result'=>['ok'=>false,'error'=>$e->getMessage()]];}}return $results;}